// Normalise getUpdates (one update or a list) into one item per human message.
const out = [];
for (const it of $input.all()) {
  const r = it.json || {};
  if (r.ok === false || r.error) continue;
  const list = r.result === undefined || r.result === null ? [] : (Array.isArray(r.result) ? r.result : [r.result]);
  for (const u of list) {
    const m = u && u.message;
    if (!m || (m.from && m.from.is_bot)) continue;
    out.push({ json: {
      event: u.event_name || '', message_id: m.message_id,
      chat_id: String((m.chat && m.chat.id) ?? ''), chat_type: (m.chat && m.chat.chat_type) || '',
      from_id: String((m.from && m.from.id) ?? ''), from_name: (m.from && (m.from.display_name || m.from.name)) || '',
      text: m.text ?? m.caption ?? '', photo_url: m.photo_url || '',
    } });
  }
}
return out.filter((i) => i.json.chat_id && i.json.from_id);

// ---- shared helpers (same block in every multi-tab Code node) ----
const noAcc = (s) => String(s ?? '').normalize('NFC').replace(/đ/g, 'd').replace(/Đ/g, 'D')
  .normalize('NFD').replace(/[̀-ͯ]/g, '').normalize('NFC');
const low = (s) => noAcc(s).toLowerCase().trim();
const truthy = (v) => v === true || ['TRUE', 'CO', 'X', '1'].includes(noAcc(v).trim().toUpperCase());
const TAB_CODES = { 'thuc don': 'td', 'thong bao': 'tb', 'lich/tkb': 'lich', 'lich': 'lich', 'tin hoat dong': 'tin' };
const TAB_EMOJI = { td: '🍽️', tb: '📢', lich: '📅', tin: '🌟' };
const tabCode = (tab) => TAB_CODES[low(tab)] || low(tab).replace(/[^a-z0-9]+/g, '');
const parseTabs = (v) => String(v || 'Thực đơn').split(',').map((t) => t.trim()).filter(Boolean);
const colLetter = (i) => { let s = ''; for (let n = i + 1; n > 0; n = Math.floor((n - 1) / 26)) s = String.fromCharCode(65 + ((n - 1) % 26)) + s; return s; };
const qTab = (tab) => `'${String(tab).replace(/'/g, "''")}'`;
const batchQuery = (tabs) => tabs.map((t) => 'ranges=' + encodeURIComponent(`${qTab(t)}!A1:Z`)).join('&');
// valueRange -> { cols: {header: letter}, rows: [{...header: value, row_number}] }
const readTab = (vr) => {
  const values = (vr && vr.values) || [];
  const header = (values[0] || []).map((h) => String(h ?? '').trim());
  const cols = {};
  header.forEach((h, i) => { if (h) cols[h] = colLetter(i); });
  const rows = values.slice(1).map((r, i) => {
    const o = { row_number: i + 2 };
    header.forEach((h, j) => { if (h) o[h] = r[j] ?? ''; });
    return o;
  });
  return { cols, rows };
};
const cell = (tab, cols, header, row) => {
  if (!cols[header]) throw new Error(`Tab "${tab}" thiếu cột "${header}"`);
  return `${qTab(tab)}!${cols[header]}${row}`;
};
const PHONE = /(?:\+?84|0)(?:\d[\s.-]?){8,10}\d/;
const nowVN = () => new Date().toLocaleString('en-GB', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false }).replace(',', '');
