const cfg = {};
for (const it of $('Đọc Config').all()) {
  const k = String(it.json['Key'] ?? '').trim();
  if (k) cfg[k] = String(it.json['Value'] ?? '').trim();
}
const botName = cfg.ZALO_BOT_NAME || '';
const tabs = parseTabs(cfg.CONTENT_TABS);
const tabByCode = {};
for (const t of tabs) tabByCode[tabCode(t)] = t;
const LABEL = { td: 'thực đơn', tb: 'thông báo', lich: 'lịch', tin: 'tin hoạt động' };

const roleOf = (r) => {
  const v = low(r);
  if (v.includes('quan tri') || v.includes('admin')) return 'admin';
  if (v.includes('duyet')) return 'approver';
  if (v.includes('nhap')) return 'entry';
  return '';
};
const active = (v) => !['false', 'khong', 'no', '0', 'ngung'].includes(low(v));
const staff = new Map();
for (const it of $('Đọc Nhân sự').all()) {
  const j = it.json;
  const id = String(j['Zalo ID'] ?? '').trim();
  if (!id || !active(j['Đang dùng'])) continue;
  const kinds = String(j['Loại nội dung'] ?? '').split(',').map((s) => tabCode(s)).filter(Boolean);
  staff.set(id, { name: String(j['Họ tên'] ?? '').trim() || id, role: roleOf(j['Vai trò']), campus: String(j['Cơ sở'] ?? '').trim(), kinds });
}
const allowed = (p, code) => !p.kinds.length || p.kinds.includes(code);

const help = (p) => {
  const mine = Object.keys(tabByCode).filter((c) => allowed(p, c));
  const lines = ['Các lệnh dùng được:'];
  const canEnter = ['entry', 'approver', 'admin'].includes(p.role);
  const canApprove = ['approver', 'admin'].includes(p.role);
  if (canEnter && mine.includes('td')) lines.push('• thực đơn 06/10: <nội dung>');
  if (canEnter && mine.includes('lich')) lines.push('• lịch 06/10: <nội dung>');
  if (canEnter && mine.includes('tb')) lines.push('• thông báo: <nội dung>');
  if (canEnter && mine.includes('tin')) lines.push('• tin: <nội dung tin hoạt động>');
  if (canApprove && mine.length) {
    lines.push(`• duyệt <mã> <hàng>   (mã: ${mine.join(', ')}; "duyệt 12" = thực đơn)`);
    lines.push('• trả lại <mã> <hàng> <lý do>');
  }
  lines.push('• trợ giúp');
  return lines.join('\n');
};
const now = new Date();
function parseDate(d, m, y) {
  d = Number(d); m = Number(m);
  if (!(d >= 1 && d <= 31 && m >= 1 && m <= 12)) return null;
  let year = y ? Number(y.length === 2 ? `20${y}` : y) : now.getFullYear();
  if (!y) { // no year: pick the year that puts the date nearest to today
    const cand = new Date(year, m - 1, d);
    if ((now - cand) / 86400000 > 180) year += 1;
  }
  return `${String(d).padStart(2, '0')}/${String(m).padStart(2, '0')}/${year}`;
}

const out = [];
for (const it of $('Tách cập nhật').all()) {
  const u = it.json;
  const person = staff.get(String(u.from_id));
  const base = { chat_id: u.chat_id, from_id: u.from_id, from_name: u.from_name, chat_type: u.chat_type, batch_query: batchQuery(tabs) };

  // Hard rule 1: never reply to anyone who is not on the staff list (could be a parent).
  if (!person) { out.push({ json: { ...base, action: 3, action_name: 'unknown', reply: '' } }); continue; }

  let text = String(u.text ?? '').normalize('NFC');
  if (botName) text = text.split(`@${botName}`).join(' ');
  text = text.replace(/^\s*@\S+\s*/, '').trim();
  const norm = noAcc(text).toLowerCase();
  const who = `${person.name} (Zalo ${u.from_id})`;
  const reply = (r) => out.push({ json: { ...base, action: 2, action_name: 'reply', reply: r } });
  const tail = (g) => text.slice(text.length - g.length).trim();

  if (u.event === 'message.image.received') { reply('Bot chưa nhận ảnh qua Zalo. Ảnh cho website xin gửi vào thư mục ảnh của trường.'); continue; }
  if (!text) { reply(help(person)); continue; }

  // ---- content commands ----
  let m, code = null, date = null, content = null;
  if ((m = norm.match(/^thuc\s*don\s+(\d{1,2})[/.-](\d{1,2})(?:[/.-](\d{2,4}))?\s*[:\-–]?\s*([\s\S]*)$/))) { code = 'td'; date = parseDate(m[1], m[2], m[3]); content = tail(m[4]); if (!date) { reply('Ngày không hợp lệ. Ví dụ: thực đơn 06/10: Sáng: cháo thịt…'); continue; } }
  else if ((m = norm.match(/^lich\s+(\d{1,2})[/.-](\d{1,2})(?:[/.-](\d{2,4}))?\s*[:\-–]?\s*([\s\S]*)$/))) { code = 'lich'; date = parseDate(m[1], m[2], m[3]); content = tail(m[4]); if (!date) { reply('Ngày không hợp lệ. Ví dụ: lịch 07/10: Họp phụ huynh 8h…'); continue; } }
  else if ((m = norm.match(/^thong\s*bao\s*[:\-–]?\s*([\s\S]*)$/))) { code = 'tb'; date = todayVN(); content = tail(m[1]); }
  else if ((m = norm.match(/^tin(?:\s*hoat\s*dong)?\s*[:\-–]\s*([\s\S]*)$/))) { code = 'tin'; date = todayVN(); content = tail(m[1]); }

  if (code) {
    const tab = tabByCode[code];
    if (!tab) { reply(`Mục ${LABEL[code]} chưa được bật cho cơ sở này.`); continue; }
    if (!['entry', 'approver', 'admin'].includes(person.role) || !allowed(person, code)) { reply(`Bạn chưa được phân quyền nhập ${LABEL[code]}.`); continue; }
    if (content.length < 5) { reply(`Thiếu nội dung ${LABEL[code]}.\n\n${help(person)}`); continue; }
    if (PHONE.test(content)) { reply('Nội dung có số điện thoại nên đã được giữ lại, chưa ghi vào bảng tính. Vui lòng bỏ thông tin cá nhân rồi gửi lại.'); continue; }
    out.push({ json: { ...base, action: 0, action_name: 'content', tab, code, range: `${qTab(tab)}!A:C`, date, content: content.slice(0, 4000),
      entered_by: `${person.name} (Zalo)`, reply: `Đã nhận ${LABEL[code]} ngày ${date}. Bản nháp sẽ được gửi cho người duyệt.` } });
    continue;
  }

  // ---- approve / return ----
  const ap = norm.match(/^duyet\s+(?:(td|tb|lich|tin)\s+)?(?:hang\s+)?(\d{1,5})\s*$/);
  const rj = norm.match(/^tra\s*lai\s+(?:(td|tb|lich|tin)\s+)?(?:hang\s+)?(\d{1,5})\s*([\s\S]*)$/);
  if (ap || rj) {
    const mm = ap || rj;
    const c = mm[1] || 'td';
    const tab = tabByCode[c];
    if (!tab) { reply(`Mã "${c}" chưa được bật cho cơ sở này.`); continue; }
    if (!['approver', 'admin'].includes(person.role) || !allowed(person, c)) { reply(`Bạn chưa được phân quyền duyệt ${LABEL[c] || c}.`); continue; }
    const row = Number(mm[2]);
    if (row < 2) { reply('Số hàng không hợp lệ.'); continue; }
    if (ap) out.push({ json: { ...base, action: 1, action_name: 'approve', tab, code: c, row_number: row, approver: who } });
    else out.push({ json: { ...base, action: 1, action_name: 'reject', tab, code: c, row_number: row, approver: who, reason: tail(rj[3]) || '(không ghi lý do)' } });
    continue;
  }
  reply(norm.startsWith('tro giup') || norm === 'help' ? help(person) : `Chưa hiểu yêu cầu.\n\n${help(person)}`);
}
return out;

