// ---- end shared helpers ----

// Validate each approve/return against the current sheet and prepare the cells to write.
const cfg = {};
for (const it of $('Đọc Config').all()) { const k = String(it.json['Key'] ?? '').trim(); if (k) cfg[k] = String(it.json['Value'] ?? '').trim(); }
const tabs = parseTabs(cfg.CONTENT_TABS);
const ranges = ($input.first().json.valueRanges) || [];
const sheet = {};
tabs.forEach((t, i) => { sheet[t] = readTab(ranges[i]); });
const out = [];
for (const it of $('Theo hành động').all(1)) {
  const a = it.json;
  const s = sheet[a.tab] || { cols: {}, rows: [] };
  const r = s.rows.find((x) => x.row_number === Number(a.row_number));
  const ref = `${a.code} ${a.row_number}`;
  let ok = false, reply, data = [];
  if (!r || !String(r['Ngày'] ?? '').trim()) reply = `Không có hàng ${a.row_number} trong tab ${a.tab}.`;
  else if (truthy(r['Đã đăng'])) reply = `${ref} (${a.tab} ngày ${r['Ngày']}) đã đăng rồi.`;
  else if (a.action_name === 'approve' && truthy(r['Duyệt'])) reply = `${ref} đã được duyệt trước đó.`;
  else if (a.action_name === 'approve' && !String(r['Bản website'] ?? '').trim()) reply = `${ref} chưa có bản nháp nên chưa duyệt được.`;
  else {
    ok = true;
    if (a.action_name === 'approve') {
      data = [
        { range: cell(a.tab, s.cols, 'Duyệt', r.row_number), values: [[true]] },
        { range: cell(a.tab, s.cols, 'Người duyệt', r.row_number), values: [[a.approver]] },
        { range: cell(a.tab, s.cols, 'Thời điểm duyệt', r.row_number), values: [[nowVN()]] },
      ];
      reply = `Đã duyệt ${ref} (${a.tab} ngày ${r['Ngày']}). Hệ thống sẽ đăng trong ít phút.`;
    } else {
      const note = [String(r['Ghi chú'] ?? '').trim(), `Trả lại bởi ${a.approver}: ${a.reason}`].filter(Boolean).join(' | ');
      data = [{ range: cell(a.tab, s.cols, 'Ghi chú', r.row_number), values: [[note]] }];
      reply = `Đã trả lại ${ref}. Lý do: ${a.reason}. Người nhập sửa trên bảng tính hoặc gửi lại.`;
    }
  }
  out.push({ json: { ...a, ok, reply, data, route: ok ? 0 : 1 } });
}
return out;

